    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address recipient) public payable {
        require(address(this).balance >= 1);
        require(caller != address(this));
        require(caller != address(0));
        require(caller != c.owner());
        require(recipient != address(0));

        c.fallback{value: 1}();

        address ownerBefore = c.owner();
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.owner() == ownerBefore && address(c).balance == cBalanceBefore);
    }
}

